module tb;

    // 1. Declare inputs as regs, outputs as wires
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] s;
    wire       overflow;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;
    integer i, j;

    // Task to check outputs against expected values using case inequality (!==)
    task check_results;
        input [7:0] exp_s;
        input       exp_ovf;
        begin
            #1; // Wait for propagation
            if ((s !== exp_s) || (overflow !== exp_ovf)) begin
                $display("ERROR: a=%d, b=%d | Got s=%d (exp %d), overflow=%b (exp %b)", 
                         $signed(a), $signed(b), $signed(s), $signed(exp_s), overflow, exp_ovf);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking
    initial begin
        // Initialize inputs
        a = 8'd0;
        b = 8'd0;
        #10;

        // Test directed vectors (covering standard, boundary, and overflow conditions)
        // 1. Zero addition
        a = 8'd0; b = 8'd0; 
        check_results(8'd0, 1'b0);

        // 2. Positive + Positive (No overflow)
        a = 8'd10; b = 8'd20; 
        check_results(8'd30, 1'b0);

        // 3. Positive + Positive (Overflow boundary: 127 + 1 = 128 -> -128)
        a = 8'd127; b = 8'd1; 
        check_results(8'h80, 1'b1);

        // 4. Negative + Negative (No overflow: -10 + -20 = -30)
        a = -8'd10; b = -8'd20; 
        check_results(-8'd30, 1'b0);

        // 5. Negative + Negative (Overflow boundary: -128 + -1 -> should overflow)
        a = 8'h80; b = 8'hFF; // -128 + -1 = -129 (underflows signed 8-bit limit of -128)
        check_results(8'h7F, 1'b1);

        // 6. Positive + Negative (Never overflows)
        a = 8'd50; b = -8'd50; 
        check_results(8'd0, 1'b0);

        // 7. Systematic bounded loop over a subset of values
        for (i = -64; i < 64; i = i + 33) begin
            for (j = -64; j < 64; j = j + 33) begin
                a = i[7:0];
                b = j[7:0];

                // Calculate expected results using 9-bit signed arithmetic to detect overflow
                begin
                    reg signed [8:0] full_sum;
                    reg             exp_ovf;
                    reg [7:0]       exp_s;

                    full_sum = $signed(a) + $signed(b);
                    exp_s    = full_sum[7:0];
                    exp_ovf  = ((i[7] == j[7]) && (exp_s[7] != i[7]));

                    check_results(exp_s, exp_ovf);
                end
            end
        end

        // Final status report
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
